<?php
session_start();
require_once __DIR__.'/../includes/config.php';
if(!isset($conn)||!($conn instanceof mysqli)) die('Database connection is not available.');
if(empty($_SESSION['admin_logged_in'])){header('Location: admin-login.php');exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function tableExists($c,$t){$t=$c->real_escape_string($t);$r=$c->query("SHOW TABLES LIKE '$t'");return $r&&$r->num_rows>0;}
function scalar($c,$sql,$default=0){$r=$c->query($sql);if($r&&($x=$r->fetch_row()))return $x[0]??$default;return $default;}
$users=tableExists($conn,'users')?(int)scalar($conn,"SELECT COUNT(*) FROM users"):0;
$riders=tableExists($conn,'riders')?(int)scalar($conn,"SELECT COUNT(*) FROM riders"):0;
$restaurants=tableExists($conn,'restaurant_users')?(int)scalar($conn,"SELECT COUNT(*) FROM restaurant_users"):0;
$orders=tableExists($conn,'orders')?(int)scalar($conn,"SELECT COUNT(*) FROM orders"):0;
$pendingRiders=tableExists($conn,'riders')?(int)scalar($conn,"SELECT COUNT(*) FROM riders WHERE LOWER(TRIM(status))='pending'"):0;
$pendingRestaurants=tableExists($conn,'restaurant_users')?(int)scalar($conn,"SELECT COUNT(*) FROM restaurant_users WHERE LOWER(TRIM(status))='pending'"):0;
$activeRiders=tableExists($conn,'riders')?(int)scalar($conn,"SELECT COUNT(*) FROM riders WHERE LOWER(TRIM(status))='active'"):0;
$todayOrders=tableExists($conn,'orders')?(int)scalar($conn,"SELECT COUNT(*) FROM orders WHERE DATE(created_at)=CURDATE()"):0;
$todaySales=tableExists($conn,'orders')?(float)scalar($conn,"SELECT COALESCE(SUM(total),0) FROM orders WHERE DATE(created_at)=CURDATE() AND LOWER(TRIM(order_status)) IN ('delivered','completed')"):0;
$monthSales=tableExists($conn,'orders')?(float)scalar($conn,"SELECT COALESCE(SUM(total),0) FROM orders WHERE YEAR(created_at)=YEAR(CURDATE()) AND MONTH(created_at)=MONTH(CURDATE()) AND LOWER(TRIM(order_status)) IN ('delivered','completed')"):0;
$openOrders=tableExists($conn,'orders')?(int)scalar($conn,"SELECT COUNT(*) FROM orders WHERE LOWER(TRIM(order_status)) NOT IN ('delivered','completed','cancelled','rejected')"):0;
$recent=[];if(tableExists($conn,'orders')){$r=$conn->query("SELECT id,order_number,total,order_status,created_at FROM orders ORDER BY id DESC LIMIT 10");if($r)while($x=$r->fetch_assoc())$recent[]=$x;}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business Control Center | Humsafar</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>*{box-sizing:border-box}body{margin:0;background:#fff8fb;color:#262626;font-family:Segoe UI,Arial,sans-serif}.page{margin-left:218px;padding:30px;min-height:100vh}.top{display:flex;justify-content:space-between;align-items:end;margin-bottom:25px}.ey{color:#ed0038;text-transform:uppercase;font-weight:900;font-size:11px;letter-spacing:1.2px}.title{font-size:31px;margin:5px 0;font-weight:900}.sub{color:#777;margin:0}.admin{background:#fff;border:1px solid #f0dce4;border-radius:12px;padding:10px 14px;font-weight:800}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.stat{background:#fff;border:1px solid #f0dce4;border-radius:15px;padding:19px;box-shadow:0 5px 18px #2a00100a}.stat i{float:right;color:#ed0038}.stat small{display:block;color:#888;font-weight:700}.stat strong{display:block;font-size:27px;margin-top:7px}.section{margin-top:28px}.section h2{font-size:19px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.card{background:#fff;border:1px solid #f0dce4;border-radius:15px;padding:19px}.card h3{margin:0 0 7px;font-size:16px}.card p{color:#777;font-size:12px;line-height:1.5}.links{display:flex;flex-wrap:wrap;gap:8px}.links a{background:#fff0f4;color:#c70032;border-radius:8px;padding:9px 11px;font-size:12px;font-weight:800;text-decoration:none}.links a:hover{background:#ed0038;color:#fff}.alerts{display:grid;grid-template-columns:1fr 1fr;gap:15px}.alert{padding:17px;border-radius:13px;background:#fff;border:1px solid #f0dce4}.alert strong{font-size:22px}.alert span{display:block;color:#777;font-size:12px;margin-top:4px}.table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #f0dce4;border-radius:14px;overflow:hidden}.table th,.table td{text-align:left;padding:12px;border-bottom:1px solid #f1e7ea;font-size:12px}.table th{font-size:11px;color:#888;text-transform:uppercase}.badge{padding:5px 9px;border-radius:999px;background:#fff0f4;color:#c50031;font-weight:800;font-size:10px}.footer-note{margin-top:25px;color:#888;font-size:11px}@media(max-width:1000px){.page{margin-left:0}.stats{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.page{padding:18px}.top{display:block}.admin{display:inline-block;margin-top:10px}.stats,.grid,.alerts{grid-template-columns:1fr}}
</style></head><body><?php include __DIR__.'/admin-sidebar.php'; ?><main class="page"><div class="top"><div><div class="ey">Humsafar Administration</div><h1 class="title">Business Control Center</h1><p class="sub">Monitor customers, restaurants, riders, orders and revenue from one place.</p></div><div class="admin"><i class="fa-solid fa-user-shield"></i> <?=h($_SESSION['admin_name']??'Administrator')?></div></div><div class="stats"><div class="stat"><i class="fa-solid fa-users"></i><small>Customers</small><strong><?=$users?></strong></div><div class="stat"><i class="fa-solid fa-store"></i><small>Restaurant Owners</small><strong><?=$restaurants?></strong></div><div class="stat"><i class="fa-solid fa-motorcycle"></i><small>Riders</small><strong><?=$riders?></strong></div><div class="stat"><i class="fa-solid fa-receipt"></i><small>Total Orders</small><strong><?=$orders?></strong></div></div><div class="section"><div class="alerts"><div class="alert"><strong><?=$pendingRestaurants?></strong><span>Restaurant applications waiting for approval</span></div><div class="alert"><strong><?=$pendingRiders?></strong><span>Rider applications waiting for approval</span></div></div></div><div class="section"><div class="grid"><div class="card"><h3>Operations</h3><p>Control the complete order lifecycle and live delivery operation.</p><div class="links"><a href="manage-orders.php">Orders</a><a href="manage-riders.php">Riders</a><a href="manage-restaurants.php">Restaurants</a></div></div><div class="card"><h3>Business & Revenue</h3><p>Review today's and monthly delivered-order revenue and manage business settings.</p><div class="links"><a href="manage-orders.php">Sales</a><a href="settings.php">Settings</a><a href="profile.php">Admin Profile</a></div></div><div class="card"><h3>People & Access</h3><p>Manage customer accounts and keep platform access under administrative control.</p><div class="links"><a href="manage-users.php">Customers</a><a href="manage-riders.php">Rider Approval</a><a href="manage-restaurants.php">Restaurant Approval</a></div></div></div></div><div class="section"><h2>Business Snapshot</h2><div class="grid"><div class="card"><h3>Today</h3><p>Orders: <strong><?=$todayOrders?></strong><br>Delivered revenue: <strong>Rs <?=number_format($todaySales,0)?></strong><br>Open orders: <strong><?=$openOrders?></strong></p></div><div class="card"><h3>This Month</h3><p>Delivered revenue: <strong>Rs <?=number_format($monthSales,0)?></strong><br>Active riders: <strong><?=$activeRiders?></strong></p></div><div class="card"><h3>Recommended Controls</h3><p>Approve partners, monitor orders, review rider activity, manage users and keep platform settings updated.</p></div></div></div><div class="section"><h2>Recent Orders</h2><?php if($recent):?><table class="table"><tr><th>Order</th><th>Total</th><th>Status</th><th>Created</th></tr><?php foreach($recent as $o):?><tr><td>#<?=h($o['order_number']?:$o['id'])?></td><td>Rs <?=number_format((float)$o['total'],0)?></td><td><span class="badge"><?=h(ucwords(str_replace('_',' ',$o['order_status'])))?></span></td><td><?=h(date('d M Y, h:i A',strtotime($o['created_at'])))?></td></tr><?php endforeach;?></table><?php else:?><div class="card">No orders found.</div><?php endif;?></div><div class="footer-note">Business Control Center uses the existing Humsafar database and existing management modules. New payment, coupon, commission and settlement tables should be added when those business features are enabled.</div></main></body></html>